options-by-expression.function:
obj -> all(`tl.accounts:Group`)
    // No representative groups
    .filter(x -> !$x.instanceOf(`tl.accounts:RepresentativeGroup`))
    // Combined with all accounts except the anonymous one
    .union(all(`tl.accounts:Person`).filter(p -> !$p.accountIsAnonymous()))

g -> all(`tl.accounts:Group`)
    // Not the group itself
    .filter(x -> $x != $g)
    // No representative groups
    .filter(x -> !$x.instanceOf(`tl.accounts:RepresentativeGroup`))
    // Combined with all accounts except the anonymous one
    .union(all(`tl.accounts:Person`).filter(p -> !$p.accountIsAnonymous()))

// All accounts
g -> all(`tl.accounts:Person`)
    // Excluding the anonymous one
    .filter(p -> !$p.accountIsAnonymous())
    // Excluding the one that is the owner of this representative group.
    .filter(p -> !$g
        .referers(`tl.accounts:Person#representativeGroup`)
        .containsElement($p))

// All accounts except the anonymous one
obj -> all(`tl.accounts:Person`)
    .filter(p -> !$p.accountIsAnonymous())

// All person contacts except the one of the anonymous account
obj -> all(`Contacts:PersonContact`)
    .filter(c -> {
        account = $c.get(`Contacts:PersonContact#account`);
        $account == null || !$account.accountIsAnonymous()
    })
